import json
import csv
import requests
from io import StringIO
# Constants
CSV_URL = 'https://example.com/data.csv'
JSON_FILE = 'data.json'
def task_func(csv_url=CSV_URL, json_file_path=JSON_FILE):
    if not isinstance(csv_url, str) or not csv_url:
        raise ValueError("Invalid CSV URL provided.")
    if not isinstance(json_file_path, str) or not json_file_path:
        raise ValueError("Invalid JSON file path provided.")

    try:
        response = requests.get(csv_url, timeout=10, verify=False)
        response.raise_for_status()
        csv_content = response.text
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to download the CSV file: {e}") from e

    try:
        csv_reader = csv.DictReader(StringIO(csv_content))
        data = [row for row in csv_reader]
    except Exception as e:
        raise ValueError(f"Error parsing the CSV content: {e}") from e

    try:
        with open(json_file_path, 'w') as json_file:
            json.dump(data, json_file, indent=4)
    except IOError as e:
        raise IOError(f"Error saving the JSON file: {e}") from e

    return json_file_path

